<template><V2Panel title="Risultati della chiusura"><p v-if="v.error" class="v2-error" role="alert">{{ v.error }}</p><button v-if="v.error" class="v2-button" @click="v.load">Aggiorna riepilogo</button><template v-if="v.summary"><div class="v2-grid-3"><article class="v2-metric"><span>MVP</span><strong style="font-size:22px">{{ v.summary.mvp_name }}</strong></article><article class="v2-metric"><span>Quota voti MVP</span><strong>{{ v.summary.percentage }}%</strong></article><article class="v2-metric"><span>Voti totali</span><strong>{{ v.summary.total_votes }}</strong></article></div><p class="v2-notice" style="margin:20px 0">{{ v.summary.draw_mode==='leaderboard'?'Premi ai migliori tifosi votanti nella classifica monete.':'Estrazione casuale tra i codici dei tifosi votanti.' }} I risultati sono salvati: riattivare e richiudere l’evento non esegue una nuova estrazione.</p><div v-if="v.summary.prizes?.length" class="v2-stack"><h3>Premi assegnati</h3><div v-for="prize in v.summary.prizes" :key="prize.id" class="v2-toolbar"><strong>{{ prize.name }}</strong><code>{{ prize.ticket_code || 'Non assegnato' }}</code><span class="v2-muted">{{ prize.nickname }}</span></div></div><p v-for="warning in v.summary.warnings" :key="warning" class="v2-notice" style="margin-top:14px">{{ warning }}</p><h3 style="margin:26px 0 14px">Riepilogo WhatsApp agli organizzatori</h3><p v-if="!v.notifications.length" class="v2-empty">Nessun destinatario abilitato al momento della chiusura.</p><div v-else class="v2-table-wrap"><table class="v2-table"><thead><tr><th>Organizzatore</th><th>Numero</th><th>Stato</th><th>Dettaglio</th></tr></thead><tbody><tr v-for="notification in v.notifications" :key="notification.id"><td>{{ notification.name || 'Organizzatore' }}</td><td>{{ notification.phone }}</td><td><span class="v2-badge">{{ v.statusLabel(notification.status) }}</span></td><td>{{ notification.error || '—' }}</td></tr></tbody></table></div><button v-if="v.canRetry" class="v2-button" style="margin-top:18px" :disabled="v.retrying" @click="v.retry">{{ v.retrying ? 'Invio in coda…' : 'Riprova notifiche non inviate' }}</button></template><p v-else-if="!v.error" role="status">Caricamento del riepilogo…</p></V2Panel></template>
<script setup>
import { inject, proxyRefs, reactive } from 'vue';
import { useController } from '../../../components/admin/AdminVotingClosure.vue?admin-v2-controller';
import V2Panel from '../shared/V2Panel.vue';
const props=defineProps({eventId:Number});const c=inject('admin-v2');
const v=proxyRefs(useController(reactive({get eventId(){return props.eventId;},get authHeaders(){return c.authHeaders;}}),event=>{if(event==='unauthorized')c.handleUnauthorized();}));
</script>
